def SELF.FederationDownstream.trueVars : (forall Nat (forall (forall Nat Bool) (app Finset.{0} (app Fin #1)))) := (lambda Nat (lambda (forall Nat Bool) (app (app (app (app Finset.filter.{0} (app Fin #1)) (lambda (app Fin #1) (app (app (app Eq.{(succ 0)} Bool) (app #1 (app (app Fin.val #2) #0))) Bool.true))) (lambda (app Fin #1) (app (app instDecidableEqBool (app #1 (app (app Fin.val #2) #0))) Bool.true))) (app (app Finset.univ.{0} (app Fin #1)) (app Fin.fintype #1)))))","proof":"{
