  "source": "/- Modified for pnp.fun: remove unused project import and transport the\n   vertex-cover forcing theorem into list-CNF minimum-true-variable semantics.\n   Upstream L-meta-727: PR #979, formal contributor fededevi, Apache-2.0.\n   This is a standard downstream formalization, not a claim of new discovery.\n   The dependency namespace pins the exact credited B bundle bytes. -/\n\ntheorem PEqualNP.Outside.L_meta_727 : ∀ (n t : ℕ) (G : SimpleGraph (Fin n)) [DecidableRel G.Adj] (v : Fin n), (∃ S : Finset (Fin n), (∀ a b : Fin n, G.Adj a b → a ∈ S ∨ b ∈ S) ∧ S.card = t) → (∀ T : Finset (Fin n), (∀ c d : Fin n, G.Adj c d → c ∈ T ∨ d ∈ T) → t ≤ T.card) → t < (Finset.univ.filter (fun u : Fin n => G.Adj v u)).card → ∀ U : Finset (Fin n), (∀ e f : Fin n, G.Adj e f → e ∈ U ∨ f ∈ U) → U.card = t → v ∈ U := by\n  intro n t G _ v _ _ hdeg U hU hUc\n  by_contra hv\n  have hsub : Finset.univ.filter (fun u : Fin n => G.Adj v u) ⊆ U := by\n    intro u hu\n    simp only [Finset.mem_filter, Finset.mem_univ, true_and] at hu\n    rcases hU v u hu with h | h\n    · exact absurd h hv\n    · exact h\n  have := Finset.card_le_card hsub\n  omega\n\nopen B_dd8e844ea24178cf06ed26a50bb2f4b1a253fd25ec68dc0c55e415c8d52cfd70.Federation\n\nnamespace FederationDownstream\n\ndef trueVars {n : ℕ} (a : Nat → Bool) : Finset (Fin n) :=\n  Finset.univ.filter (fun u => a u.val = true)\n\ndef assignmentOf {n : ℕ} (S : Finset (Fin n)) (k : Nat) : Bool :=\n  if h : k < n then decide ((⟨k, h⟩ : Fin n) ∈ S) else false\n\ntheorem assignmentOf_at {n : ℕ} (S : Finset (Fin n)) (u : Fin n) :\n    assignmentOf S u.val = decide (u ∈ S) := by\n  simp [assignmentOf, u.isLt]\n\ntheorem trueVars_assignmentOf {n : ℕ} (S : Finset (Fin n)) :\n    trueVars (assignmentOf S) = S := by\n  ext u\n  simp [trueVars, assignmentOf_at]\n\n/-- A vertex of degree above the minimum number of true variables must be\n    true in every minimum model. Bundle B then removes its incident clauses.\n    The cardinality is only over the graph's finite vertex set. -/\ntheorem forced_vertex_reduction {n : ℕ} (G : SimpleGraph (Fin n))\n    [DecidableRel G.Adj] (v : Fin n) (a : Nat → Bool)\n    (hsat : evalCNF a (relationCNF G.Adj) = true)\n    (hmin : ∀ b : Nat → Bool, evalCNF b (relationCNF G.Adj) = true →\n      (trueVars (n := n) a).card ≤ (trueVars (n := n) b).card)\n    (hdeg : (trueVars (n := n) a).card <\n      (Finset.univ.filter (fun u : Fin n => G.Adj v u)).card) :\n    a v.val = true ∧\n      evalCNF a (relationCNF (fun u w => u ≠ v ∧ w ≠ v ∧ G.Adj u w)) = true := by\n  have hcover : ∀ u w : Fin n, G.Adj u w →\n      u ∈ trueVars (n := n) a ∨ w ∈ trueVars (n := n) a := by\n    intro u w hR\n    simpa [trueVars] using (relationCNF_semantics G.Adj a).mp hsat u w hR\n  have hminimal : ∀ T : Finset (Fin n),\n      (∀ u w : Fin n, G.Adj u w → u ∈ T ∨ w ∈ T) →\n      (trueVars (n := n) a).card ≤ T.card := by\n    intro T hT\n    have ht : evalCNF (assignmentOf T) (relationCNF G.Adj) = true := by\n      apply (relationCNF_semantics G.Adj (assignmentOf T)).mpr\n      intro u w huw\n      simpa [assignmentOf_at] using hT u w huw\n    simpa [trueVars_assignmentOf] using hmin (assignmentOf T) ht\n  have hv_mem := PEqualNP.Outside.L_meta_727 n (trueVars (n := n) a).card G v\n    ⟨trueVars a, hcover, rfl⟩ hminimal hdeg (trueVars a) hcover rfl\n  have hv : a v.val = true := by simpa [trueVars] using hv_mem\n  have hfix : Function.update a v.val true = a := by\n    funext k\n    by_cases hk : k = v.val\n    · subst k\n      simp [hv]\n    · simp [Function.update_of_ne hk]\n  have reduced := B_dd8e844ea24178cf06ed26a50bb2f4b1a253fd25ec68dc0c55e415c8d52cfd70.Federation.graphCNF_delete_vertex G v a\n  rw [hfix, hsat] at reduced\n  exact ⟨hv, reduced.symm⟩\n\nend FederationDownstream\n",
